void lf_flush( void  )
{        
    os_pip_flush( lf_pip ) ;  
                
    os_pip_insert( lf_pip , LF_CMD_RESET , 100 ) ;  
        
    TRACE_LF("\n\r[LF_CMD_RESET_FLUSH]\n\r");          
}		

